use vstd::prelude::*;

verus! {
    fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
        requires
            arr.len() < 0x1_0000_0000, // Ensure the length is within reasonable bounds
        ensures
            result.len() == arr.len() && 
            forall|i: nat| 0 <= i < arr.len() ==> result[i] == arr[i],
    {
        let mut result: Vec<i8> = Vec::new();
        let mut idx: nat = 0;

        // Initialize the result vector with the same length as arr
        result.resize(arr.len(), 0);

        while idx < arr.len() as nat
            invariant
                idx <= arr.len() as nat,
                result.len() == arr.len() && 
                forall|i: nat| 0 <= i < idx ==> result[i] == arr[i],
            decreases arr.len() as nat - idx,
        {
            result[idx] = arr[idx as usize]; // Copy the element
            idx = idx + 1; // Move to the next index
        }

        result
    }
}
